//! Exercise real App capability issuance/authorization and the existing parent mapper.
use super::*;
use crate::{app::{App,AndroidNativeRentalBindingRecord,AndroidNativeHostBindingRecord,AndroidNativeTrustBootstrapRecord,host::{HostId,AppId},user::UserId}};
use common::config::{Config,StorageConfig};
async fn fixture()->(App,crate::app::AndroidNativeLaunchTokenRecord,crate::app::AndroidNativeStreamTicketRecord){
 let root=std::env::temp_dir().join(format!("cg-qualification-authority-{}",uuid::Uuid::new_v4()));std::fs::create_dir(&root).unwrap();let mut config=Config::default();config.data_storage=StorageConfig::Json{path:root.join("data.json").to_string_lossy().into_owned(),session_expiration_check_interval:std::time::Duration::from_secs(300)};config.web_server.default_user_id=None;let app=App::new(config).await.unwrap();
 let binding=AndroidNativeRentalBindingRecord{handoff_binding_id:uuid::Uuid::new_v4().to_string(),claim_id:"claim_qualification".into(),prepare_operation_id:None,rental_session_id:None};
 let issued=app.issue_android_native_launch_token(UserId(9001),HostId(1),AppId(1379015545),AndroidNativeHostBindingRecord{name:"loopback".into(),address:"127.0.0.1".into(),http_port:47989,https_port:None,external_port:None,unique_id:None,local_ip:None},AndroidNativeTrustBootstrapRecord{paired:false,pair_mode:"fixture".into(),client_unique_id:None,client_certificate_pem:None,client_private_key_pem:None,server_certificate_pem:None},Some(binding)).await;
 let(_,ticket)=app.consume_android_native_launch_token_with_stream_ticket(&issued.launch_token).await.unwrap();(app,issued,ticket)
}
fn now()->u64{std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_millis()as u64}
fn complete()->AndroidNativeRentalBindingRecord{AndroidNativeRentalBindingRecord{handoff_binding_id:uuid::Uuid::new_v4().to_string(),claim_id:"claim_qualification".into(),prepare_operation_id:Some("prepare_qualification_1234".into()),rental_session_id:Some("rental_qualification".into())}}
#[actix_web::test]
async fn official_sibling_binding_qualifies_context_without_upgrading_prelogin_or_new_root(){
 let(app,first,parent)=fixture().await;let initial=app.authorize_android_native_stream_ticket_for_stream(&parent.stream_ticket,parent.host_id,parent.app_id).await.unwrap();assert!(context(&initial,1,"a".repeat(32),now()).is_none());
 let binding=complete();let second=app.issue_android_native_sibling_launch_token(&first.session_id,first.user_id,first.host_id,first.app_id,first.host_binding.clone(),first.trust_bootstrap.clone(),binding.clone()).await.unwrap();
 let(_,ticket)=app.consume_android_native_launch_token_with_stream_ticket(&second.launch_token).await.unwrap();let authorized=app.authorize_android_native_stream_ticket_for_stream(&ticket.stream_ticket,ticket.host_id,ticket.app_id).await.unwrap();let c=context(&authorized,2,"b".repeat(32),now()).unwrap();
 assert_eq!(c.native_session_id,parent.session_id);assert_eq!(c.claim_id,binding.claim_id);assert_eq!(c.rental_session_id,binding.rental_session_id);assert_eq!(c.handoff_binding_id,binding.handoff_binding_id);assert_eq!(c.generation,2);assert!(c.authority_expires_ms<=parent.expires_at_unix_ms);assert_ne!(ticket.stream_ticket,parent.stream_ticket);
 let original=app.authorize_android_native_stream_ticket_for_stream(&parent.stream_ticket,parent.host_id,parent.app_id).await.unwrap();assert!(original.rental_binding.unwrap().rental_session_id.is_none());
 if let Ok(dir)=std::env::var("CG_QA_TEST_EVIDENCE_DIR"){let file=std::fs::OpenOptions::new().write(true).create_new(true).open(std::path::PathBuf::from(dir).join(format!("authority-app-{}.json",std::process::id()))).unwrap();serde_json::to_writer_pretty(file,&serde_json::json!({"same_native_root":true,"same_claim":true,"prelogin_not_upgraded":true,"authority_not_extended":true,"rental_id_carried":"rental_qualification","generation":2,"issued_tickets_distinct":true,"context_contains_no_bearer":true,"scope":"real App methods; backend running-billing auth uses synthetic trusted fixture, not a live rental or HTTP auth test","billing_mutations":0})).unwrap();}
}
#[actix_web::test]
async fn sibling_qualification_rejects_wrong_identity_and_terminal_root(){let(app,first,parent)=fixture().await;for i in 0..4{let mut binding=complete();let mut user=first.user_id;let mut host=first.host_id;let mut appid=first.app_id;match i{0=>binding.claim_id="claim_wrong".into(),1=>user=UserId(4),2=>host=HostId(4),_=>appid=AppId(4)};assert!(app.issue_android_native_sibling_launch_token(&first.session_id,user,host,appid,first.host_binding.clone(),first.trust_bootstrap.clone(),binding).await.is_err());}
 app.update_android_native_session_lifecycle(Some(&parent.stream_ticket),Some(&first.token_id),Some(&first.session_id),"session_revoke_requested".into(),None,None).await.unwrap();assert!(app.issue_android_native_sibling_launch_token(&first.session_id,first.user_id,first.host_id,first.app_id,first.host_binding.clone(),first.trust_bootstrap.clone(),complete()).await.is_err());assert!(app.authorize_android_native_stream_ticket_for_stream(&parent.stream_ticket,parent.host_id,parent.app_id).await.is_err());}
